"""widget.py — the moy-5 figure as a native anywidget (no iframe). The front-end (dist/widget.js, dist/widget.css) is generated by build.mjs.

    from widget import Moy5RouteFigure
    w = Moy5RouteFigure(state=1)             # JupyterLab: put `w` at the end of a cell.   marimo: mo.ui.anywidget(w)
    w.state = 10                             # kernel -> figure: walk to state 10 (the effort ladder)
    w.lang = "en"; w.theme = "light"; w.t = 4   # t = P_x moved along h1 on states 0 and 7 (drawing only)
    w.cone = False                           # v2.2: hide the overlay (the cone, the Dandelin sphere and the cut) on states 0 and 7; True (the default) shows it. Drawing only (not data).
    w.state, w.done, w.reading               # figure -> kernel: the state the reader pressed, whether the figure stopped moving, what is on the screen (text and numbers)
    w.kernel_check()                         # the kernel side recount (route 5): the readout on screen vs the raw jsonl, for the states that print a raw count in their readout
"""
import json
import pathlib

import anywidget
import traitlets

HERE = pathlib.Path(__file__).resolve().parent
CONFIG = json.loads((HERE / "config.json").read_text(encoding="utf-8"))
STATES = CONFIG["chapters"][-1][2] + 1        # never typed: the last state of the last chapter in config.json


class Moy5RouteFigure(anywidget.AnyWidget):
    _esm = HERE / "dist" / "widget.js"
    _css = HERE / "dist" / "widget.css"

    state = traitlets.Int(0).tag(sync=True)
    lang = traitlets.Enum(["ja", "en"], default_value="ja").tag(sync=True)
    t = traitlets.Int(-1).tag(sync=True)
    theme = traitlets.Enum(["dark", "light", "auto"], default_value="dark").tag(sync=True)
    cone = traitlets.Bool(True).tag(sync=True)
    done = traitlets.Bool(True).tag(sync=True)
    reading = traitlets.Dict({}).tag(sync=True)

    @traitlets.validate("state")
    def _clamp_state(self, proposal):
        return max(0, min(STATES - 1, int(proposal["value"])))

    def kernel_check(self):
        """the readout the figure shows now, against the same count made here from the raw jsonl (check_claims.py's reader; not the pack, not the page's JS)"""
        import sys
        sys.path.insert(0, str(HERE))
        import check_claims as cc
        n = lambda files, model, arm, field: sum(bool(r.get(field)) for f in files for r in cc.rows_of(f) if r.get("model") == model and r.get("arm") == arm and r.get("raw"))
        O6, O3, P3 = ["results_neq6_moy5_20261019_claude-opus-5-5.jsonl"], ["results_neq3_moy5_20261019_claude-opus-5-5.jsonl"], ["results_prf3_20261021.jsonl"]
        want = {10: f"medium {n(O6, 'claude-opus-5-5', 'A/Q2@medium', 'cut_in_conjecture')} · high {n(O6, 'claude-opus-5-5', 'A/Q2@high', 'cut_in_conjecture')} · max {n(O6, 'claude-opus-5-5', 'A/Q2@max', 'cut_in_conjecture')} ‖ xhigh {n(O3, 'claude-opus-5-5', 'A/Q2', 'cut_in_conjecture')}",
                18: f"Opus {n(P3, 'claude-opus-5-5', 'P5', 'lat_sym')} → {n(P3, 'claude-opus-5-5', 'P5B', 'lat_sym')}",
                1: f"LAT_SYM {n(P3, 'claude-opus-5-5', 'P5B', 'lat_sym')} / 10"}
        r = self.reading or {}
        s = r.get("state")
        if s not in want:
            return {"state": s, "checked": False, "why": f"state {s} prints no raw count in its readout; try {sorted(want)}"}
        return {"state": s, "checked": True, "ok": want[s] in r.get("readout", ""), "readout": r.get("readout"), "expected_part": want[s]}
